import{_ as a,o as t,c as i,ao as r}from"./chunks/framework.CDuh1GR-.js";const p=JSON.parse('{"title":"Aim and origins","description":"","frontmatter":{},"headers":[],"relativePath":"aim.md","filePath":"aim.md","lastUpdated":null}'),s={name:"aim.md"};function o(n,e,h,m,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Aim-and-origins" tabindex="-1">Aim and origins <a class="header-anchor" href="#Aim-and-origins" aria-label="Permalink to &quot;Aim and origins {#Aim-and-origins}&quot;">​</a></h1><p>The aim is a transparent estimate of how far the outbreak has already grown, and of how much each published data stream contributes to that estimate. Most infections are not yet reported, so the current size has to be inferred from the surveillance data that are available. What the estimate can and cannot support is set out in the <a href="./limitations">limitations</a>.</p><h2 id="Origins-of-this-work" tabindex="-1">Origins of this work <a class="header-anchor" href="#Origins-of-this-work" aria-label="Permalink to &quot;Origins of this work {#Origins-of-this-work}&quot;">​</a></h2><p>This work began as a replication of the <a href="/BVDOutbreakSize/previews/PR884/references#mccabe2026">McCabe and others (2026)</a> report. It has since evolved into a real-time joint Bayesian estimate of the current outbreak size. The model is a discrete-time renewal process with a time-varying reproduction number, fitted to more of the available data streams than the original. What is shared with that report and what has changed is set out component by component in the <a href="/BVDOutbreakSize/previews/PR884/methods#Comparison-with-published-estimates">comparison with published estimates</a>. The <a href="/BVDOutbreakSize/previews/PR884/sensitivity#Comparison-with-McCabe-et-al.">comparison with McCabe et al.</a> sets the current estimates against theirs.</p>',4)])])}const f=a(s,[["render",o]]);export{p as __pageData,f as default};
